import {SECTION_TYPES} from '/shared/estimator.mjs';
const $=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v||0),n=(v,d=2)=>Number(v||0).toLocaleString('en-US',{maximumFractionDigits:d}),date=v=>v?new Date(v.length===10?v+'T12:00:00Z':v).toLocaleDateString('en-US'):'—';
const current=new Date(),monthParts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit'}).formatToParts(current),year=Number(monthParts.find(p=>p.type==='year').value),mon=Number(monthParts.find(p=>p.type==='month').value);
const previous=new Date(Date.UTC(year,mon-2,1)).toISOString().slice(0,7),first=new Date(Date.UTC(year,mon-4,1)).toISOString().slice(0,7);
const s={me:null,admin:null,adminFilter:'attention',errorArea:'all',settings:null,tab:'radar',radar:null,sources:[],projects:[],estimates:[],jobs:[],members:[],finances:null,staff:null,filters:{from:first,to:previous,state:'Todos',cities:[],mode:'all',kind:'All',tier:'All',status:'All',order:'cities',q:'',includeArchived:'',page:1},chosen:null,project:null,estimate:null,result:null,dirty:true,modal:null,upload:null,busy:false};
const statuses=['Novo','Analisar','Contatado','Orçamento enviado','Ganho','Perdido','Descartado'];const statusLabel={'Novo':'New','Analisar':'Review','Contatado':'Contacted','Orçamento enviado':'Proposal sent','Ganho':'Won','Perdido':'Lost','Descartado':'Discarded'};
const opt=(value,label,selected)=>'<option value="'+e(value)+'"'+(value===selected?' selected':'')+'>'+e(label)+'</option>';
const input=(label,name,value='',type='text',extra='')=>'<label>'+e(label)+'<input name="'+e(name)+'" type="'+type+'" value="'+e(value)+'" '+extra+'></label>';
const action=(name,label,id='',kind='')=>'<button type="button" data-action="'+name+'" data-id="'+e(id)+'" class="'+kind+'">'+e(label)+'</button>';
const native=source=>!['report','portal'].includes(source.mode);
function clearWorkspace(){s.me=null;s.admin=null;s.csrf='';s.settings=null;s.projects=[];s.estimates=[];s.finances=null;s.staff=null;s.estimate=null;s.project=null;s.result=null;s.chosen=null;s.modal=null;s.upload=null;s.tab='radar';s.poll=false;s.saved=false;}
function notice(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'show error':'show';clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.className='',error?12000:7000);}
async function api(path,body,method=body?'POST':'GET'){
 const res=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRF-Token':s.csrf||''}:{},body:body?JSON.stringify(body):undefined});const j=await res.json();
 if(!res.ok){if(res.status===401&&path!=='/api/login'){clearWorkspace();render();}throw new Error(j.error||'Falha na operação.');}return j;
}
function query(extra={}){const p=new URLSearchParams({...s.filters,...extra,cities:s.filters.cities.join(',')});return p.toString();}
async function radar(){s.radar=await api('/api/radar?'+query());s.sources=s.radar.sources;}
async function projects(){s.projects=(await api('/api/projects')).projects;s.estimates=(await api('/api/estimates')).estimates;}
async function refresh(){if(s.tab==='radar'||s.tab==='coverage')await radar();if(s.tab==='projects')await projects();render();}
function newSection(type='Roof / Rafters'){return {id:crypto.randomUUID(),type,name:type,geometry:'rectangle',length:'',width:'',directArea:'',pitchRise:6,quantity:1,sides:1,openings:0,targetR:49,cavityDepth:0,wastePct:0,layers:[{materialId:'cc',mode:'fixed',inches:2},{materialId:'oc',mode:'fill',inches:0}]};}
function draft(projectId){s.estimate={projectId,title:'Insulation estimate',input:{sections:[newSection()],mobilization:s.settings.pricing.mobilization,otherCost:0,discount:0,manualSubtotal:'',clientNotes:''}};s.result=null;s.dirty=true;s.saved=false;s.tab='estimate';}
async function uploadFile(u,confirm){
 const q=new URLSearchParams({sourceId:u.sourceId,month:u.month,filename:u.file.name,confirm:confirm?'1':'0'});
 const res=await fetch('/api/import-file?'+q,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':s.csrf||''},body:u.file});
 const j=await res.json();if(!res.ok)throw new Error(j.error||'File import failed.');return j;
}
function header(){return '<header class="top"><a class="brand" href="/"><span class="brand-mark">MS</span><span>Moriah System<small>PERMIT INTELLIGENCE · BETA</small></span></a><nav>'+[['radar','Permit Radar'],['projects','Projects & Estimates'],['payments','Payments'],['employees','Employees'],['coverage','Sources & Coverage'],...(s.me.systemAdmin?[['admin','Admin'],['errors','Errors']]:[]),['settings','Settings']].map(([id,label])=>action('tab',label,id,s.tab===id?'active':'')).join('')+'</nav><div class="account"><span>'+e(s.me.email)+'</span>'+action('logout','Sign out')+'</div></header>';}
function filters(){return '<form class="filterbar" data-form="filters">'+input('From','from',s.filters.from,'month','required')+input('To','to',s.filters.to,'month','required')+'<label>State<select name="state">'+['Todos','MA','CT','RI'].map(x=>opt(x,x==='Todos'?'All states':x,s.filters.state)).join('')+'</select></label><details class="cities"><summary>Cities · '+(s.filters.cities.length?s.filters.cities.length+' selected':'All')+'</summary><div class="city-picker"><input type="search" placeholder="Search cities…" data-city-search aria-label="Search cities">'+action('allCities','Clear city selection')+s.sources.filter(x=>s.filters.state==='Todos'||x.state===s.filters.state).map(c=>'<label class="city-option"><input type="checkbox" data-city="'+e(c.id)+'" '+(s.filters.cities.includes(c.id)?'checked':'')+'>'+e(c.city)+' <small>'+c.state+'</small></label>').join('')+'</div></details><label class="search-label">Search<input name="q" value="'+e(s.filters.q)+'" placeholder="Address, permit or contractor"></label><label class="archive-toggle"><input type="checkbox" name="includeArchived" value="1" '+(s.filters.includeArchived==='1'?'checked':'')+'> Include archived (12+ months)</label><button class="primary" type="submit">Search permits</button></form>';}
function radarView(){
 const d=s.radar;if(!d)return '<p class="empty">Loading projects…</p>';
 return '<section class="title"><div><p class="eyebrow">FROM PERMIT TO PROPOSAL</p><h1>Find your next project.</h1><p>New homes, additions, ADUs and major renovations with municipal evidence.</p></div><div class="actions">'+action('collect','Refresh permit data','','primary')+action('exportRadar','Export CSV')+'</div></section>'+filters()+
 '<section class="metrics"><div><small>Matching projects</small><strong>'+d.total+'</strong></div><div><small>Permits loaded</small><strong>'+n(d.recordsLoaded,0)+'</strong></div><div><small>Cities with records</small><strong>'+d.cityCounts.filter(x=>x.count).length+'</strong></div><div><small>Integrated workflow</small><strong class="small">Permit → Project → Proposal</strong></div></section>'+
 '<section class="panel"><div class="table-tools"><label>Show<select data-filter="mode">'+opt('qualified','Qualified opportunities',s.filters.mode)+opt('all','All projects / review',s.filters.mode)+'</select></label><label>Type<select data-filter="kind">'+['All','New house','Addition','ADU','Gut renovation','Conversion','Commercial','Insulation','Other'].map(x=>opt(x,x==='All'?'All types':x,s.filters.kind)).join('')+'</select></label><label>Priority<select data-filter="tier">'+['All','HOT','GOOD','POSSIBLE','REVIEW'].map(x=>opt(x,x==='All'?'All':x,s.filters.tier)).join('')+'</select></label><label>Status<select data-filter="status">'+['All',...statuses].map(x=>opt(x,x==='All'?'All statuses':statusLabel[x]||x,s.filters.status)).join('')+'</select></label><label>Sort by<select data-filter="order">'+opt('cities','Balance across cities',s.filters.order)+opt('score','Highest score',s.filters.order)+'</select></label></div>'+
 (d.truncated?'<p class="warning">The 30,000-permit query limit was reached. Narrow the period or select fewer cities.</p>':'')+
 '<div class="table-scroll"><table><thead><tr><th>Project / address</th><th>Type</th><th>Priority</th><th>Issued</th><th>Declared value</th><th>Status</th><th></th></tr></thead><tbody>'+d.projects.map(p=>'<tr><td><button class="link" data-action="lead" data-id="'+e(p.key)+'">'+e(p.master.address||'Address unavailable')+'</button><small>'+e(p.master.city)+', '+p.master.state+' · '+p.records.length+' permit(s)</small></td><td>'+e(p.kind)+'</td><td><span class="badge '+p.tier.toLowerCase()+'">'+p.tier+'</span> <small>'+p.score+'/100</small></td><td>'+date(p.master.issued)+'</td><td>'+(p.value?money(p.value):'Not provided')+'</td><td>'+e(statusLabel[p.review.status]||p.review.status)+'</td><td>'+action('convert','Create project',p.key)+'</td></tr>').join('')+'</tbody></table></div>'+
 (!d.projects.length?'<div class="empty"><h2>No projects match your filters</h2><p>Check Sources & Coverage. A pending city does not mean no permits exist.</p></div>':'')+
 '<footer class="pagination"><span>Page '+d.page+' of '+d.pages+' · '+d.total+' projects</span><div>'+action('prev','Previous')+action('next','Next')+'</div></footer></section><p class="muted">Opportunity scores are estimates, not proof of project stage. Municipal inspection evidence is required to confirm stage.</p>';
}
function projectsView(){return '<section class="title"><div><p class="eyebrow">ESTIMATE PIPELINE</p><h1>Projects & Estimates.</h1><p>One address, all measurements and saved proposals.</p></div>'+action('newProject','New project','','primary')+'</section><div class="project-grid">'+s.projects.map(p=>'<article class="panel project-card"><small>'+e(p.client||'Client not provided')+'</small><h2>'+e(p.name)+'</h2><p>'+e(p.address)+'</p><p>'+e(p.phone)+' '+e(p.email)+'</p><div class="actions">'+action('newEstimate','Create estimate',p.id,'primary')+action('editProject','Edit project',p.id)+'</div><div class="saved-estimates">'+s.estimates.filter(x=>x.projectId===p.id).map(x=>'<div><span>'+e(x.title)+'<small>'+date(x.createdAt)+' · '+money(x.total)+'</small></span>'+action('openEstimate','Abrir',x.id)+'</div>').join('')+'</div></article>').join('')+'</div>'+(!s.projects.length?'<section class="panel empty"><h2>Comece por uma obra do radar ou crie seu projeto.</h2><p>Os projetos e orçamentos são privados do seu workspace.</p></section>':'');}
function sectionEditor(section,i){
 const prefix='data-section="'+i+'" ',field=(label,key,type='number',extra='')=>'<label>'+e(label)+'<input '+prefix+'data-field="'+key+'" type="'+type+'" value="'+e(section[key]??'')+'" '+(type==='number'?'min="0" step="any"':'')+' '+extra+'></label>';
 return '<article class="panel section-editor"><header><span class="number">'+(i+1)+'</span><div><h2>'+e(section.name)+'</h2><small>Medidas em pés decimais ou 12\' 6". Descontos já incluem todos os lados.</small></div>'+action('removeSection','Remover',i)+'</header><div class="form-grid">'+field('Nome','name','text')+'<label>Seção<select '+prefix+'data-field="type">'+SECTION_TYPES.map(t=>opt(t,t,section.type)).join('')+'</select></label><label>Geometria<select '+prefix+'data-field="geometry">'+[['rectangle','Retângulo'],['triangle','Triângulo / gable'],['roof-plan','Projeção do telhado'],['direct','Área medida diretamente']].map(([v,l])=>opt(v,l,section.geometry)).join('')+'</select></label>'+field('Comprimento (ft)','length','text')+field('Largura / altura (ft)','width','text')+field('Área direta (sqft)','directArea')+field('Pitch: rise / 12','pitchRise')+field('Quantidade','quantity')+'<label>Lados contados<select '+prefix+'data-field="sides">'+opt('1','Um lado',String(section.sides))+opt('2','Ambos os lados',String(section.sides))+'</select></label>'+field('Descontos totais (sqft)','openings')+field('R-value alvo','targetR')+field('Profundidade da cavidade (in)','cavityDepth')+field('Perdas adicionais (%)','wastePct')+'</div><div class="assembly"><h3>Montagem of materiais</h3><div class="recipes">'+action('recipeOC','Somente OC',i)+action('recipeCC','Somente CC',i)+action('recipeHybrid','2" CC + OC fill',i)+'</div>'+section.layers.map((l,j)=>{const m=s.settings.materials.find(m=>m.id===l.materialId);return '<div class="layer"><label>Material<select '+prefix+'data-layer="'+j+'" data-layer-field="materialId">'+s.settings.materials.map(m=>opt(m.id,m.name,l.materialId)).join('')+'</select></label><label>Espessura<select '+prefix+'data-layer="'+j+'" data-layer-field="mode">'+opt('fixed','Definida',l.mode)+(m?.kind==='foam'?opt('fill','Completar o R restante',l.mode):'')+'</select></label><label>Polegadas<input type="number" min="0" step="0.01" '+prefix+'data-layer="'+j+'" data-layer-field="inches" value="'+e(l.inches||0)+'" '+(l.mode==='fill'?'disabled':'')+'></label>'+action('removeLayer','×',i+':'+j)+'</div>';}).join('')+action('addLayer','Adicionar camada',i)+'</div></article>';
}
function resultView(){
 const r=s.result;if(!r)return '<div class="empty"><h3>Calcule para conferir materiais e preço.</h3><p>O servidor valida as medidas e recalcula os valores antes of salvar.</p></div>';
 return '<div id="result-status" class="'+(s.dirty?'warning':'muted')+'">'+(s.dirty?'Valores alterados. Calcule novamente.':'Cálculo atualizado.')+'</div><div class="metrics"><div><small>Área contada</small><strong>'+n(r.totalArea)+' sqft</strong></div><div><small>Custo estimado</small><strong>'+money(r.cost)+'</strong></div><div><small>Proposta com imposto</small><strong>'+money(r.total)+'</strong></div></div>'+
 (r.warnings.length?'<div class="warning">'+r.warnings.map(e).join('<br>')+'</div>':'')+
 '<div class="table-scroll"><table><thead><tr><th>Material</th><th>Consumo</th><th>Compra arredondada</th><th>Board feet</th><th>Custo</th></tr></thead><tbody>'+r.materials.map(m=>'<tr><td>'+e(m.name)+'</td><td>'+n(m.units)+' '+e(m.unitLabel)+'</td><td>'+m.purchaseUnits+'</td><td>'+n(m.boardFeet)+'</td><td>'+money(m.purchaseCost)+'</td></tr>').join('')+'</tbody></table></div><p class="muted">'+e(r.gallonNote)+'</p><p class="muted">'+e(r.codeNote)+'</p><div class="table-scroll"><table><thead><tr><th>Seção</th><th>Área</th><th>Espessura</th><th>R calculado / alvo</th><th>Valor</th></tr></thead><tbody>'+r.sections.map(x=>'<tr><td>'+e(x.name)+'</td><td>'+n(x.net)+' sqft</td><td>'+n(x.depth)+'"</td><td>'+n(x.installedR,1)+' / '+x.targetR+'</td><td>'+money(x.saleAmount)+'</td></tr>').join('')+'</tbody></table></div><div class="totals"><span>Subtotal '+money(r.subtotal)+'</span><span>Desconto '+money(r.discount)+'</span><span>Imposto '+money(r.tax)+'</span><strong>Total '+money(r.total)+'</strong></div>';
}
function estimateView(){
 if(!s.estimate)return '<div class="empty">Escolha um projeto para começar.</div>';const p=s.projects.find(p=>p.id===s.estimate.projectId)||s.project;
 return '<section class="title"><div><p class="eyebrow">INSULATION ESTIMATOR</p><h1>'+e(p?.name||'Orçamento')+'</h1><p>'+e(p?.address||'')+'</p></div><div class="actions">'+action('tab','Voltar aos projetos','projects')+action('calculate','Calcular','','primary')+action('exportEstimate','Materiais CSV')+action('saveEstimate','Salvar orçamento','','save-estimate')+(s.estimate.id?action('print','Imprimir proposta',s.estimate.id):'')+'</div></section><section class="panel quote-settings"><div class="form-grid"><label>Título<input data-quote="title" value="'+e(s.estimate.title)+'"></label><label>Mobilização (USD)<input type="number" min="0" step=".01" data-quote-input="mobilization" value="'+e(s.estimate.input.mobilization)+'"></label><label>Outros custos (USD)<input type="number" min="0" step=".01" data-quote-input="otherCost" value="'+e(s.estimate.input.otherCost)+'"></label><label>Desconto (USD)<input type="number" min="0" step=".01" data-quote-input="discount" value="'+e(s.estimate.input.discount)+'"></label><label>Subtotal manual opcional (USD)<input type="number" min=".01" step=".01" data-quote-input="manualSubtotal" value="'+e(s.estimate.input.manualSubtotal??'')+'"></label></div><label>Nota para o cliente<textarea data-quote-input="clientNotes">'+e(s.estimate.input.clientNotes||'')+'</textarea></label></section>'+s.estimate.input.sections.map(sectionEditor).join('')+'<div class="actions add-section">'+action('addSection','Adicionar seção')+action('sample','Carregar amostra of validação')+'</div><section class="panel result-panel"><h2>Materiais e resumo</h2>'+resultView()+'</section>';
}
function coverageView(){const d=s.radar;return '<section class="title"><div><p class="eyebrow">TRACEABLE MUNICIPAL SOURCES</p><h1>Sources & Coverage.</h1><p>A registered source does not mean data was collected. Pending and incomplete data are displayed.</p></div><div class="actions">'+action('import','Import permits JSON')+(s.me.systemAdmin?action('openUpload','Import file (PDF/CSV/XLSX)'):'')+(s.me.systemAdmin?action('newSource','Add city','','primary'):'')+'</div></section>'+filters()+'<div class="source-grid">'+s.sources.filter(c=>s.filters.state==='Todos'||s.filters.state===c.state).filter(c=>!s.filters.cities.length||s.filters.cities.includes(c.id)).map(c=>{const checks=(d?.coverage||[]).filter(x=>x.sourceId===c.id),count=d?.cityCounts.find(x=>x.sourceId===c.id)?.count||0,complete=checks.filter(x=>x.status==='complete').length,last=checks.toSorted((a,b)=>b.checkedAt.localeCompare(a.checkedAt))[0];return '<article class="panel source"><div><span class="badge">'+c.state+'</span><small>'+e(native(c)?'Native collector':'Report / municipal portal')+'</small></div><h2>'+e(c.city)+'</h2><strong>'+n(count,0)+' stored permits</strong><p>'+complete+' of '+(d?.months.length||0)+' months fully collected.</p><p><b>Status:</b> '+e(last?({'complete':'Collected','partial':'Partial','pending':'Pending','unavailable':'Unavailable'}[last.status]||last.status):'Not tested')+'</p><p class="muted">'+e(last?.message||'Not checked for this period.')+'</p><a href="'+e(c.url)+'" target="_blank" rel="noreferrer">Open official source ↗</a><footer>'+(native(c)?action('collectSource','Refresh period',c.id):'<span class="muted">Requires verified report import; no automated collector.</span>')+'</footer></article>';}).join('')+'</div><section class="panel jobs"><h2>Recent collection jobs</h2>'+s.jobs.slice(0,15).map(j=>'<div><span>'+e(j.sourceId)+' · '+j.month+' <b>'+e(j.status)+'</b></span><small>'+e(j.message)+'</small></div>').join('')+'</section>';}
function adminView(){
 const d=s.admin;if(!d)return '<section class="title"><div><p class="eyebrow">ADMINISTRATOR</p><h1>Admin.</h1><p>Loading…</p></div></section>';
 const byId=new Map(d.sources.map(x=>[x.id,x])),checks=new Map(d.checks.map(x=>[x.sourceId,x]));
 const latest=new Map();for(const c of d.coverage){const list=latest.get(c.sourceId)||[];list.push(c);latest.set(c.sourceId,list);}
 const rows=d.sources.map(src=>{
  const list=(latest.get(src.id)||[]).sort((a,b)=>b.month.localeCompare(a.month)),count=st=>list.filter(c=>c.status===st).length;
  const good=list.filter(c=>['complete','partial'].includes(c.status)&&c.count>0).sort((a,b)=>b.checkedAt.localeCompare(a.checkedAt))[0];
  const bad=list.find(c=>c.status==='unavailable')||list.find(c=>c.status==='pending')||list[0];
  const level=!src.automatic?'manual':count('unavailable')?'failed':count('pending')?'pending':count('partial')?'partial':list.length?'ok':'never';
  return {src,list,level,good,bad,counts:{complete:count('complete'),partial:count('partial'),pending:count('pending'),failed:count('unavailable')},check:checks.get(src.id)};
 });
 const labels={failed:'Failed',pending:'Pending',partial:'Partial',ok:'Complete',never:'Not collected yet',manual:'Manual import'};
 const shown=rows.filter(r=>s.adminFilter==='all'||(s.adminFilter==='attention'?['failed','pending','partial','never'].includes(r.level):r.level===s.adminFilter));
 const filterOpts=[['attention','Needs attention'],['failed','Failed'],['pending','Pending'],['partial','Partial'],['ok','Complete'],['manual','Manual import'],['all','All']].map(([v,l])=>opt(v,l,s.adminFilter)).join('');
 const counts=Object.fromEntries(Object.keys(labels).map(k=>[k,rows.filter(r=>r.level===k).length]));
 return '<section class="title"><div><p class="eyebrow">ADMINISTRATOR</p><h1>Admin.</h1><p>Registered accounts, collection health by city and source-link checks. Only system administrators see this page.</p></div><div class="actions">'+action('openUpload','Import file (PDF/CSV/XLSX)')+action('retryFailed','Retry failed collections')+action('checkSources','Check source links','','primary')+'</div></section>'
 +'<section class="panel"><h2>Registered accounts ('+d.users.length+')</h2><div class="table-scroll"><table><thead><tr><th>Email</th><th>Role</th><th>Workspace</th><th>System admin</th><th>Active sessions</th><th>Created</th></tr></thead><tbody>'+d.users.map(u=>'<tr><td>'+e(u.email)+'</td><td>'+e(u.role)+'</td><td>'+e(u.workspace)+'</td><td>'+(u.systemAdmin?'Yes':'No')+'</td><td>'+u.activeSessions+'</td><td>'+date(u.createdAt)+'</td></tr>').join('')+'</tbody></table></div><p class="muted">To add a user to a workspace, use Settings. Password hashes are never shown.</p></section>'
 +'<section class="panel"><h2>Collection health</h2><p class="muted">'+Object.entries(labels).map(([k,l])=>l+': <b>'+counts[k]+'</b>').join(' · ')+'</p><label>Show<select data-admin-filter>'+filterOpts+'</select></label><div class="table-scroll"><table><thead><tr><th>City</th><th>Status</th><th>Months (complete / partial / pending / failed)</th><th>Last successful collection</th><th>Latest message</th><th>Source link</th></tr></thead><tbody>'
 +shown.map(r=>'<tr><td><b>'+e(r.src.city)+'</b> <small>'+e(r.src.state)+'</small></td><td><span class="badge">'+e(labels[r.level])+'</span></td><td>'+r.counts.complete+' / '+r.counts.partial+' / '+r.counts.pending+' / '+r.counts.failed+'</td><td>'+(r.good?e(r.good.month)+' · '+r.good.count+' permits':'—')+'</td><td>'+e(r.bad?r.bad.message:(r.src.reason||'No collection yet.'))+'</td><td>'+(r.check?(r.check.ok?'OK':'<b>Problem</b>')+' · '+e(r.check.note)+' <small>'+date(r.check.checkedAt)+'</small>':'<small>not checked</small>')+'</td></tr>').join('')
 +'</tbody></table></div></section>';
}
function errorsView(){
 const d=s.admin;if(!d)return '<section class="title"><div><p class="eyebrow">ADMINISTRATOR</p><h1>Errors.</h1><p>Loading…</p></div></section>';
 const names={collection:'City collection','source-link':'City link check',import:'File import',server:'Server'},byId=new Map(d.sources.map(x=>[x.id,x]));
 const all=d.errors||[],shown=all.filter(x=>s.errorArea==='all'||x.area===s.errorArea);
 const opts=[['all','All areas'],...Object.entries(names)].map(([v,l])=>opt(v,l+(v==='all'?' ('+all.length+')':' ('+all.filter(x=>x.area===v).length+')'),s.errorArea)).join('');
 return '<section class="title"><div><p class="eyebrow">ADMINISTRATOR</p><h1>Errors.</h1><p>Every failure recorded by the system, newest first, with the full reason. Old permits are never deleted when a collection fails.</p></div><div class="actions">'+action('retryFailed','Retry failed collections')+action('checkSources','Check source links','','primary')+'</div></section>'
 +'<section class="panel"><label>Area<select data-error-area>'+opts+'</select></label>'+(shown.length?'<div class="table-scroll"><table><thead><tr><th>When</th><th>Area</th><th>City</th><th>Month</th><th>Reason</th></tr></thead><tbody>'+shown.map(x=>'<tr><td>'+date(x.createdAt)+'</td><td><span class="badge">'+e(names[x.area]||x.area)+'</span></td><td>'+e(byId.get(x.sourceId)?.city||x.sourceId||'—')+'</td><td>'+e(x.month||'—')+'</td><td>'+e(x.message)+'</td></tr>').join('')+'</tbody></table></div>':'<p>No errors recorded.</p>')+'</section>';
}
